fn prime_num(n: u64) -> bool {
    if n == 2 {
        return true; // 2 is prime
    }
    if n < 2 || n % 2 == 0 {
        return false; // Exclude numbers less than 2 and even numbers greater than 2
    }
    
    let limit = (n as f64).sqrt() as u64; // Calculate the integer square root of n
    for k in (3..=limit).step_by(2) { // Check only odd numbers
        if n % k == 0 {
            return false; // Found a divisor, n is not prime
        }
    }
    
    true // No divisors found, n is prime
}